from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import TenantUserProfileLink

class ToggleTenantSyncView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        link_id = request.data.get('link_id')
        enable_sync = request.data.get('enable_sync', True)

        try:
            link = TenantUserProfileLink.objects.get(id=link_id, user=request.user)
        except TenantUserProfileLink.DoesNotExist:
            return Response({'error': 'Profile link not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        link.sync_to_public_schema = enable_sync
        link.save(update_fields=['sync_to_public_schema'])
        return Response({'id': link.id, 'sync_enabled': link.sync_to_public_schema})
